import{_ as t,o as n,c as e,a2 as r}from"./chunks/framework.Desnpdez.js";const s="/mbit-mcpo-proxy-download/guide/images/assistant-bridge-card.png",a="/mbit-mcpo-proxy-download/guide/images/preset-microsoft-365-add-dialog.png",i="/mbit-mcpo-proxy-download/guide/images/connections-edit-modal.png",c="/mbit-mcpo-proxy-download/guide/images/connections-my-list.png",b=JSON.parse('{"title":"Connections","description":"","frontmatter":{},"headers":[],"relativePath":"everyday/connections.md","filePath":"everyday/connections.md"}'),l={name:"everyday/connections.md"};function d(p,o,g,m,h,u){return n(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to &quot;Connections&quot;">​</a></h1><p><strong>Connections</strong> lists everything your assistants can talk to: ready-made <strong>Library</strong> entries and your own definitions under <strong>My connections</strong>.</p><h2 id="library-vs-my-connections" tabindex="-1">Library vs My connections <a class="header-anchor" href="#library-vs-my-connections" aria-label="Permalink to &quot;Library vs My connections&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Library</strong></td><td>Curated presets (Telekom Telecontext, Microsoft 365, Obsidian, and others). Tap <strong>+</strong> to add. Some cards show <strong>Docker</strong> if that preset expects Docker on your Mac—the bridge itself does not.</td></tr><tr><td><strong>My connections</strong></td><td>Everything you added. Enable, disable, edit, delete, or open <strong>Tools</strong> for fine control.</td></tr></tbody></table><p><img src="'+s+'" alt="Connections — Library tab with preset cards"></p><h2 id="my-connections-list" tabindex="-1">My connections list <a class="header-anchor" href="#my-connections-list" aria-label="Permalink to &quot;My connections list&quot;">​</a></h2><p>Each row shows the display name and how it runs (for example <strong>Stdio (local process)</strong> for many presets).</p><p><img src="'+a+'" alt="Connections — My connections list"></p><p>Per connection you typically have:</p><ul><li><strong>Tools</strong> — optional list or toggles, depending on the server.</li><li><strong>Disable</strong> / <strong>Enable</strong> — soft switch without deleting.</li><li><strong>Edit</strong> — change name, command, environment, or transport.</li><li><strong>Delete</strong> — remove the connection.</li></ul><p><strong>Export configuration</strong> saves a backup of your setup—useful before big changes.</p><h2 id="add-a-connection-manually" tabindex="-1">Add a connection manually <a class="header-anchor" href="#add-a-connection-manually" aria-label="Permalink to &quot;Add a connection manually&quot;">​</a></h2><p>Tap <strong>+ Add connection</strong>. You usually get this form when a vendor gives you a command to run.</p><p><img src="'+i+'" alt="Add connection form"></p><ul><li><strong>Name</strong> — what you see in lists.</li><li><strong>Transport</strong> — leave as your vendor instructs (<strong>Stdio</strong> is common for local tools).</li><li><strong>Command</strong> / <strong>Arguments</strong> — copy exactly from the vendor’s guide.</li><li><strong>Environment variables</strong> — one <code>KEY=value</code> per line (often API keys).</li><li><strong>Enabled</strong> — on by default.</li></ul><p><img src="'+c+'" alt="Edit connection example"></p><p>After saving, return to <strong>Home</strong> and use <strong>Apply changes</strong> if the app prompts you.</p><h2 id="preset-specific-help" tabindex="-1">Preset-specific help <a class="header-anchor" href="#preset-specific-help" aria-label="Permalink to &quot;Preset-specific help&quot;">​</a></h2><ul><li><strong><a href="./../presets/telekom-telecontext.html">Telekom Telecontext</a></strong></li><li><strong><a href="./../presets/microsoft-365.html">Microsoft 365</a></strong></li><li><strong><a href="./../presets/obsidian.html">Obsidian notes</a></strong></li></ul><h2 id="import-many-connections-at-once" tabindex="-1">Import many connections at once <a class="header-anchor" href="#import-many-connections-at-once" aria-label="Permalink to &quot;Import many connections at once&quot;">​</a></h2><p>For a JSON file in <code>mcp.json</code> shape, use <strong><a href="./settings.html#import-json-mcpjson">Settings → Import</a></strong> (power users).</p><h2 id="chrome-browser-optional" tabindex="-1">Chrome browser (optional) <a class="header-anchor" href="#chrome-browser-optional" aria-label="Permalink to &quot;Chrome browser (optional)&quot;">​</a></h2><p>If your build shows <strong>Chrome browser</strong> under Integrations, it is for advanced workflows that attach to a Chrome instance via DevTools. Follow any in-app hints after your administrator enables the feature.</p>',23)])])}const f=t(l,[["render",d]]);export{b as __pageData,f as default};
